48	/**
49	 * Create a Checkout session that pays for a prorated server UPGRADE directly (no
50	 * wallet pre-fund), applying the customer's wallet balance to the split. The CARD
51	 * is charged only `cardCents` (the remainder after wallet credit); the FULL
52	 * proration is recorded in metadata as `chargeCents` so the confirm route debits
53	 * the whole proration back out of the wallet. Since creditCheckoutSession credited
54	 * only the card portion, the wallet naturally absorbs the difference — the wallet
55	 * is never touched before the card clears.
56	 */
57	export async function createResizeCheckout(
58	  user: { id: string; email: string },
59	  cardCents: number,
60	  resize: { serverId: string; planId: string; planName?: string; prorateCents: number },
61	): Promise<string | null> {
62	  if (!stripeConfigured() || cardCents <= 0) return null;
63	  const base = process.env.APP_URL ?? "http://localhost:3000";
64	  const session = await stripe().checkout.sessions.create({
65	    mode: "payment",
66	    customer_email: user.email,
67	    line_items: [
68	      {
69	        price_data: {
70	          currency: "usd",
71	          product_data: { name: `Nxeon VPS upgrade${resize.planName ? ` — ${resize.planName}` : ""}` },
72	          unit_amount: cardCents,
73	        },
74	        quantity: 1,
75	      },
76	    ],
77	    metadata: {
78	      nxeonUserId: user.id,
79	      // chargeCents = the FULL proration to debit on confirm (not the card amount).
80	      nxeonResize: JSON.stringify({ serverId: resize.serverId, planId: resize.planId, chargeCents: resize.prorateCents }).slice(0, 490),
81	    },
82	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
83	    cancel_url: `${base}/dashboard/servers/${resize.serverId}?canceled=1`,
84	  });
85	  return session.url;
86	}
