88	/**
89	 * Create a Checkout session that pays for a prorated per-server DISK EXPANSION
90	 * directly (no wallet pre-fund), applying the customer's wallet balance to the
91	 * split. Structurally identical to createResizeCheckout: the CARD is charged only
92	 * `cardCents` (the remainder after wallet credit) while the FULL proration travels
93	 * in metadata as `chargeCents`, so the confirm route debits the whole proration
94	 * back out of the wallet against the just-credited card amount. The wallet is
95	 * never touched before the card clears.
96	 */
97	export async function createDiskExpandCheckout(
98	  user: { id: string; email: string },
99	  cardCents: number,
100	  expand: { serverId: string; addGB: number; hostname?: string; prorateCents: number },
101	): Promise<string | null> {
102	  if (!stripeConfigured() || cardCents <= 0) return null;
103	  const base = process.env.APP_URL ?? "http://localhost:3000";
104	  const session = await stripe().checkout.sessions.create({
105	    mode: "payment",
106	    customer_email: user.email,
107	    line_items: [
108	      {
109	        price_data: {
110	          currency: "usd",
111	          product_data: {
112	            name: `Nxeon +${expand.addGB} GB disk${expand.hostname ? ` — ${expand.hostname}` : ""}`,
113	            // The one-way nature is on the Stripe page itself, not just in our UI.
114	            description: "Permanent storage expansion — disk space can be added but never removed.",
115	          },
116	          unit_amount: cardCents,
117	        },
118	        quantity: 1,
119	      },
120	    ],
121	    metadata: {
122	      nxeonUserId: user.id,
123	      // chargeCents = the FULL proration to debit on confirm (not the card amount).
124	      nxeonDiskExpand: JSON.stringify({
125	        serverId: expand.serverId,
126	        addGB: expand.addGB,
127	        chargeCents: expand.prorateCents,
128	      }).slice(0, 490),
129	    },
130	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
131	    cancel_url: `${base}/dashboard/servers/${expand.serverId}?canceled=1`,
132	  });
133	  return session.url;
134	}
