136	/** For the confirm route: the disk-expansion intent attached to a paid session, if any. */
137	export async function getCheckoutDiskExpandIntent(
138	  sessionId: string,
139	): Promise<{ userId: string; serverId: string; addGB: number; chargeCents: number } | null> {
140	  if (!stripeConfigured()) return null;
141	  try {
142	    const session = await stripe().checkout.sessions.retrieve(sessionId);
143	    const userId = session.metadata?.nxeonUserId;
144	    const raw = session.metadata?.nxeonDiskExpand;
145	    if (!userId || !raw || session.payment_status !== "paid") return null;
146	    const parsed = JSON.parse(raw) as { serverId: string; addGB: number; chargeCents: number };
147	    return { userId, serverId: parsed.serverId, addGB: parsed.addGB, chargeCents: parsed.chargeCents };
148	  } catch {
149	    return null;
150	  }
151	}
