170	/** For the confirm route: the order intent attached to a paid session, if any. */
171	export async function getCheckoutOrderIntent(
172	  sessionId: string,
173	): Promise<{ userId: string; intent: OrderIntent } | null> {
174	  if (!stripeConfigured()) return null;
175	  try {
176	    const session = await stripe().checkout.sessions.retrieve(sessionId);
177	    const userId = session.metadata?.nxeonUserId;
178	    const raw = session.metadata?.nxeonOrder;
179	    if (!userId || !raw || session.payment_status !== "paid") return null;
