1	import { NextRequest, NextResponse } from "next/server";
2	import {
3	  creditCheckoutSession,
4	  getCheckoutDiskExpandIntent,
5	  getCheckoutOrderIntent,
6	  getCheckoutResizeIntent,
7	  stripeConfigured,
8	} from "@/lib/stripe";
9	import { db } from "@/lib/db";
10	import { placeOrder } from "@/lib/order";
11	import { applyResize } from "@/lib/resize";
12	import { applyDiskExpand } from "@/lib/disk-expand";
13	
14	/**
15	 * Checkout success redirect target. Verifies the session server-side and credits
16	 * the wallet immediately — no webhook (and therefore no HTTPS) required. When the
17	 * session carries a direct-pay order intent, the server is provisioned right away
18	 * (once — guarded by the idempotent credit).
19	 */
20	export async function GET(req: NextRequest) {
21	  const base = process.env.APP_URL ?? "";
22	  const sessionId = req.nextUrl.searchParams.get("session_id");
23	  if (!stripeConfigured() || !sessionId) {
24	    return NextResponse.redirect(`${base}/dashboard/billing`);
25	  }
26	  try {
27	    const credited = await creditCheckoutSession(sessionId);
28	    const order = await getCheckoutOrderIntent(sessionId);
29	    if (order) {
30	      // `credited` is true only on the first successful credit for this session,
31	      // so provisioning runs exactly once even if the confirm URL is reloaded.
32	      if (credited) {
33	        const user = await db.user.findUnique({ where: { id: order.userId } });
34	        if (user) {
35	          try {
36	            const serverId = await placeOrder(user, order.intent);
37	            return NextResponse.redirect(`${base}/dashboard/servers/${serverId}`);
38	          } catch {
39	            // Payment captured but provisioning failed — funds are in the wallet.
40	            return NextResponse.redirect(`${base}/dashboard/deploy?paid=1`);
41	          }
42	        }
43	      }
44	      return NextResponse.redirect(`${base}/dashboard/servers`);
45	    }
46	    // Paid server upgrade: apply the resize exactly once. `credited` is true only
47	    // on the first successful credit for this session (guarded by the UNIQUE
48	    // stripeSessionId), so applyResize runs at most once even if this URL is
49	    // reloaded — mirrors the deploy path's single-shot provisioning. The card
50	    // funds were just credited to the wallet; applyResize debits them back out
51	    // (chargeCents), netting to zero.
52	    const resize = await getCheckoutResizeIntent(sessionId);
53	    if (resize) {
54	      if (credited) {
55	        try {
56	          await applyResize({
57	            serverId: resize.serverId,
58	            planId: resize.planId,
59	            actorUserId: resize.userId,
60	            chargeCents: resize.chargeCents,
61	          });
62	          return NextResponse.redirect(`${base}/dashboard/servers/${resize.serverId}`);
63	        } catch {
64	          // Payment captured but the resize couldn't be queued (e.g. server now
65	          // busy) — funds are in the wallet; surface the paid state.
66	          return NextResponse.redirect(`${base}/dashboard/servers/${resize.serverId}?paid=1`);
67	        }
68	      }
69	      return NextResponse.redirect(`${base}/dashboard/servers/${resize.serverId}`);
70	    }
71	    // Paid per-server DISK EXPANSION: identical single-shot contract to the resize
72	    // branch above. `credited` gates on the UNIQUE(stripeSessionId) credit, so a
73	    // reloaded/replayed confirm URL can never queue a second DISK_EXPAND job or
74	    // charge twice. The card funds were just credited to the wallet; applyDiskExpand
75	    // debits the FULL proration (chargeCents) straight back out, netting to zero.
76	    const expand = await getCheckoutDiskExpandIntent(sessionId);
77	    if (expand) {
78	      if (credited) {
79	        try {
80	          await applyDiskExpand({
81	            serverId: expand.serverId,
82	            addGB: expand.addGB,
83	            actorUserId: expand.userId,
84	            chargeCents: expand.chargeCents,
85	          });
86	          return NextResponse.redirect(`${base}/dashboard/servers/${expand.serverId}?tab=resize`);
87	        } catch {
88	          // Payment captured but the expansion couldn't be queued (e.g. server now
89	          // busy) — funds are in the wallet; surface the paid state.
90	          return NextResponse.redirect(`${base}/dashboard/servers/${expand.serverId}?paid=1`);
91	        }
92	      }
93	      return NextResponse.redirect(`${base}/dashboard/servers/${expand.serverId}?tab=resize`);
94	    }
95	    return NextResponse.redirect(`${base}/dashboard/billing?paid=1`);
96	  } catch {
97	    return NextResponse.redirect(`${base}/dashboard/billing?pending=1`);
98	  }
99	}
