1	"use client";
2	
3	import { useState, useTransition } from "react";
4	import { applyCouponToTopup } from "@/lib/actions-growth";
5	import type { CouponApplyResult } from "@/lib/growth";
6	
7	const COUPON_COOKIE = "nxeon_coupon";
8	// Nominal amount used only to validate the code before the user picks an amount.
9	const PREVIEW_CENTS = 2500;
10	
11	function setCookie(code: string) {
12	  document.cookie = `${COUPON_COOKIE}=${encodeURIComponent(code)}; path=/; max-age=${60 * 60}; SameSite=Lax`;
13	}
14	function clearCookie() {
15	  document.cookie = `${COUPON_COOKIE}=; path=/; max-age=0; SameSite=Lax`;
16	}
17	
18	/**
19	 * Promo-code entry for the wallet top-up flow. On a valid code it stores the
20	 * code in a short-lived cookie which `topUp` reads and applies to the real
21	 * top-up amount (this keeps the existing AddFunds form untouched).
22	 */
23	export function CouponField() {
24	  const [code, setCode] = useState("");
25	  const [applied, setApplied] = useState<{ code: string; label: string } | null>(null);
26	  const [error, setError] = useState<string | null>(null);
27	  const [pending, start] = useTransition();
28	
29	  const apply = () => {
30	    setError(null);
31	    const trimmed = code.trim();
32	    if (!trimmed) {
33	      setError("Enter a promo code.");
34	      return;
35	    }
36	    start(async () => {
37	      const res: CouponApplyResult = await applyCouponToTopup(trimmed, PREVIEW_CENTS);
38	      if (res.ok) {
39	        setCookie(res.code);
40	        setApplied({ code: res.code, label: res.label });
41	        setError(null);
42	      } else {
43	        clearCookie();
44	        setApplied(null);
45	        setError(res.error);
46	      }
47	    });
48	  };
49	
50	  const remove = () => {
51	    clearCookie();
52	    setApplied(null);
53	    setCode("");
54	    setError(null);
55	  };
56	
57	  if (applied) {
58	    return (
59	      <div className="flex flex-wrap items-center gap-3 rounded-lg border border-emerald-500/30 bg-emerald-500/[0.06] px-3 py-2 text-sm">
60	        <span className="font-medium text-emerald-300">
61	          Code <span className="font-mono">{applied.code}</span> applied — {applied.label}
62	        </span>
63	        <span className="text-xs text-slate-400">Bonus is credited when you add funds.</span>
64	        <button type="button" onClick={remove} className="btn-ghost ml-auto py-1 text-xs">
65	          Remove
66	        </button>
67	      </div>
68	    );
69	  }
70	
71	  return (
72	    <div>
73	      <label className="label">Promo code</label>
74	      <div className="flex items-center gap-2">
75	        <input
76	          className="input w-48 uppercase"
77	          value={code}
78	          onChange={(e) => setCode(e.target.value)}
79	          placeholder="WELCOME10"
80	          maxLength={32}
81	          onKeyDown={(e) => {
82	            if (e.key === "Enter") {
83	              e.preventDefault();
84	              apply();
85	            }
86	          }}
87	        />
88	        <button type="button" className="btn-secondary py-2" onClick={apply} disabled={pending}>
89	          {pending ? "Checking…" : "Apply"}
90	        </button>
91	      </div>
92	      {error && <p className="mt-2 text-sm text-red-400">{error}</p>}
93	    </div>
94	  );
95	}
