40	/**
41	 * Compute the extra wallet credit a coupon grants for a top-up of `baseCents`.
42	 * PERCENT -> baseCents * value%; FIXED_CENTS / CREDIT_CENTS -> flat `value` cents.
43	 */
44	function couponBonusForTopup(coupon: Coupon, baseCents: number): number {
45	  switch (coupon.kind) {
46	    case "PERCENT":
47	      return Math.round((baseCents * coupon.value) / 100);
48	    case "FIXED_CENTS":
49	    case "CREDIT_CENTS":
50	      return coupon.value;
51	    default:
52	      return 0;
53	  }
54	}
