146	  const rawMax = String(formData.get("maxRedemptions") ?? "").trim();
147	  const parsed = couponSchema.safeParse({
148	    code: formData.get("code"),
149	    kind: formData.get("kind"),
150	    scope: formData.get("scope"),
151	    value: formData.get("value"),
152	    firstTimeOnly: formData.get("firstTimeOnly") === "on",
153	    minAmountCents: rawMin === "" ? undefined : rawMin,
154	    maxRedemptions: rawMax === "" ? undefined : rawMax,
155	    expiresAt: rawExpires === "" ? undefined : rawExpires,
156	    note: formData.get("note") || undefined,
157	  });
158	  if (!parsed.success) {
159	    return { error: parsed.error.issues[0]?.message ?? "Invalid coupon." };
160	  }
161	  const data = parsed.data;
162	  if (data.kind === "PERCENT" && data.value > 100) {
163	    return { error: "Percent value must be between 1 and 100." };
