252	/**
253	 * If `userId` was referred and hasn't been rewarded yet, credit BOTH the referred
254	 * user and their referrer with REFERRAL_REWARD_CENTS, exactly once. Guarded by an
255	 * atomic claim on `referralRewardedAt` so concurrent paid actions can't double-pay.
256	 * Callable from `topUp` / `orderServer` in lib/actions.ts after a paid action.
257	 */
258	export async function maybeRewardReferral(userId: string): Promise<boolean> {
259	  await assertInternalGrowthCaller(userId);
260	  // Feature flag: the referral program can be switched off platform-wide.
261	  if (!(await getSettingBool("feature_referrals", true))) return false;
262	
263	  const reward = referralRewardCents();
264	  if (reward <= 0) return false;
265	
266	  const user = await db.user.findUnique({ where: { id: userId } });
267	  if (!user || !user.referredById || user.referralRewardedAt) return false;
268	  const referrerId = user.referredById;
269	
270	  // Atomically claim the reward; if another concurrent action already did, bail.
271	  const claim = await db.user.updateMany({
272	    where: { id: userId, referralRewardedAt: null, referredById: { not: null } },
273	    data: { referralRewardedAt: new Date() },
274	  });
275	  if (claim.count === 0) return false;
276	
277	  await db.$transaction([
278	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: reward } } }),
279	    db.walletTransaction.create({
280	      data: { userId, amountCents: reward, description: "Referral bonus — welcome reward" },
281	    }),
282	    db.user.update({ where: { id: referrerId }, data: { balanceCents: { increment: reward } } }),
283	    db.walletTransaction.create({
284	      data: {
285	        userId: referrerId,
286	        amountCents: reward,
287	        description: "Referral bonus — you referred a friend",
288	      },
289	    }),
290	  ]);
291	
292	  // Best-effort in-app notifications.
293	  try {
294	    await db.notification.createMany({
295	      data: [
296	        {
297	          userId,
298	          title: `You earned a $${(reward / 100).toFixed(2)} referral bonus`,
299	          href: "/dashboard/billing",
300	        },
301	        {
302	          userId: referrerId,
303	          title: `A friend you referred just joined — $${(reward / 100).toFixed(2)} added`,
304	          href: "/dashboard/refer",
305	        },
306	      ],
307	    });
308	  } catch {
309	    /* best-effort */
310	  }
311	  return true;
312	}
