94	  // in lib/promotions.ts so the wizard's displayed price === the checkout charge.
95	  const hasPromo = promoPercent > 0;
96	  const promoCents = (regular: number) => Math.round(regular * (1 - promoPercent / 100));
97	  // Only redirect to Stripe as the result of an EXPLICIT Deploy submit. The flag is
98	  // armed in the Deploy button's onClick (and the Enter-on-final-step path) and
99	  // consumed here, so a stale `checkoutUrl` in state can never redirect on its own —
100	  // e.g. after a back-button remount (ref starts false) or an unrelated re-render.
