371	/**
372	 * Deploy flow that does NOT require pre-funding the wallet. If the wallet covers
373	 * the order (or it's a free admin grant) it provisions immediately; otherwise it
374	 * returns a Stripe Checkout URL for the order total, and the Stripe confirm route
375	 * provisions the server on successful payment.
376	 */
377	export async function payAndDeploy(
378	  prev: any,
379	  formData: FormData,
380	): Promise<{ error?: string; checkoutUrl?: string }> {
381	  const user = await requireUser();
382	  // Spend path: same impersonation guard as orderServer.
383	  await assertNotImpersonating();
384	  // Same per-user server cap as orderServer (this is the card-pay deploy path).
385	  const limitErr = await serverLimitError(user.id);
386	  if (limitErr) return { error: limitErr };
387	  const intent = intentFromFormData(formData);
388	
389	  let quote;
390	  try {
391	    quote = await orderQuote(intent);
392	  } catch (e) {
393	    if (e instanceof OrderError) return { error: e.message };
394	    throw e;
395	  }
396	
397	  const isAdmin = user.role === "ADMIN";
398	  const freePath = !!intent.free && isAdmin;
399	
400	  // Wallet-aware split. The customer's Review screen computes the exact same split
401	  // (lib/wallet-split.ts) from the same inputs, so what they see === what we charge.
402	  // `useWallet` defaults ON (only "0" turns it off) so existing forms keep applying
403	  // the balance. Free admin grants skip the split entirely (no money moves).
404	  const useWallet = formData.get("useWallet") !== "0";
405	  const { walletApplied, cardCents } = freePath
406	    ? { walletApplied: 0, cardCents: 0 }
407	    : walletSplit({ dueCents: quote.chargeCents, balanceCents: user.balanceCents, useWallet });
408	
409	  // Card portion is $0 (free admin grant, or the wallet fully covers the charge) →
410	  // provision straight away. placeOrder debits the FULL chargeCents from the wallet
411	  // (or nothing, for a free grant); the balance check inside it holds because a
412	  // $0 card portion means balance >= chargeCents.
413	  if (freePath || cardCents <= 0) {
414	    let serverId: string;
415	    try {
416	      serverId = await placeOrder(user, intent);
417	    } catch (e) {
418	      if (e instanceof OrderError) return { error: e.message };
419	      throw e;
420	    }
421	    redirect(`/dashboard/servers/${serverId}`);
422	  }
423	
424	  // Card portion > 0 → charge ONLY the remainder on the card (not the full total).
425	  // On payment success the confirm route credits this card amount to the wallet and
426	  // then placeOrder debits the full chargeCents, so the wallet naturally absorbs
427	  // `walletApplied` and the card the rest — the wallet is never touched before the
428	  // card clears. (walletApplied is implied by cardCents vs. the recomputed charge,
429	  // so it needs no separate metadata field.)
430	  const url = await createOrderCheckout(user, cardCents, intent);
431	  if (!url) return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
432	  return { checkoutUrl: url };
433	}
