import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { PageHeader, EmptyState } from "@/components/ui/primitives";
import { DeployWizard } from "@/components/customer/DeployWizard";
import { capacitySnapshot } from "@/lib/capacity";
import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
import { extraDiskPerGbCents } from "@/lib/disk-expand";
import { currentPromo } from "@/lib/promotions";

export const dynamic = "force-dynamic";

export default async function DeployPage() {
  const user = await requireUser();
  // The active intro promo (Summer Sale etc.). payAndDeploy charges the promo
  // price on the first term (lib/order.ts), so the wizard must DISPLAY it too —
  // otherwise displayed ($8.99) ≠ charged ($6.29). Computed server-side so the
  // shown promo matches the one checkout applies.
  const promo = currentPromo(new Date());
  const [plans, images, sshKeys, nodes, capacity, freeIps] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    db.osTemplate.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { name: "asc" }] }),
    db.sshKey.findMany({ where: { userId: user.id }, select: { id: true, name: true, publicKey: true } }),
    db.node.findMany({ where: { enabled: true }, select: { id: true, name: true, publicIp: true } }),
    capacitySnapshot(),
    db.dedicatedIp.count({ where: { status: "FREE" } }),
  ]);

  return (
    <div className="space-y-6">
      <PageHeader title="Deploy a server" sub="NVMe-backed KVM virtual machines, live in under two minutes." />
      {capacity.nearCapacity && (
        <div className="rounded-2xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
          <span className="font-semibold">Host is filling up.</span> We&apos;re at{" "}
          {Math.round(capacity.ramUtilization * 100)}% of committed RAM. Larger plans may be briefly unavailable.
        </div>
      )}
      {plans.length === 0 || images.length === 0 ? (
        <EmptyState
          title="Deployments are temporarily unavailable"
          sub="No active plans or images are configured. Please check back soon or contact support."
        />
      ) : (
        <DeployWizard
          plans={plans.map((p) => ({
            id: p.id,
            name: p.name,
            cpuCores: p.cpuCores,
            ramMB: p.ramMB,
            diskGB: p.diskGB,
            bandwidthTB: p.bandwidthTB,
            priceCents: p.priceCents,
            storageTier: p.storageTier,
          }))}
          images={images.map((o) => ({
            id: o.id,
            slug: o.slug,
            name: o.name,
            category: o.category,
            family: o.family,
            version: o.version,
            logo: o.logo,
            minRamMB: o.minRamMB,
            minDiskGB: o.minDiskGB,
            licenseRequired: o.licenseRequired,
            featured: o.featured,
          }))}
          nodes={nodes}
          sshKeys={sshKeys.map((k) => ({ id: k.id, name: k.name }))}
          isAdmin={user.role === "ADMIN"}
          balanceCents={user.balanceCents}
          dedicatedIpAvailable={freeIps > 0}
          dedicatedIpPriceCents={await dedicatedIpMonthlyCents()}
          extraDiskPriceCentsPerGb={await extraDiskPerGbCents()}
          promoPercent={promo.discountPercent}
          promoLabel={promo.label}
        />
      )}
    </div>
  );
}
